  Exercise(id: '10033', name: '中位绳索夹胸', categoryPath: '力量训练 / 胸部训练 / 中胸', description: '滑轮调至与胸部齐平高度，站姿微微前倾，手肘保持固定微弯，双手从两侧向前做夹胸，手在胸前交汇。不是推，是夹！全程中胸持续受力，底部不卸力，非常适合胸中缝、胸外侧塑形。', tips: ['滑轮调至胸部齐平高度','站姿微微前倾','手肘固定微弯','不是推是夹全程持续受力'], sets: 3, reps: 15, restSeconds: '30', difficulty: '中级', imageSvg: '中胸', imageUrl: 'https://images.pexels.com/photos/5496589/pexels-photo-5496589.jpeg', videoPath: '', weight: '0'),
  Exercise(id: '10034', name: '低位绳索平板推胸', categoryPath: '力量训练 / 胸部训练 / 中胸', description: '滑轮最低，躺平板凳，握住绳索把手做类似平板哑铃卧推的推起。下放时绳索持续拉扯，中胸离心张力很强，弥补哑铃杠铃底部容易卸力的缺点。', tips: ['滑轮放最低位','躺平板凳','下放时绳索持续拉扯','弥补底部卸力缺点'], sets: 3, reps: 12, restSeconds: '45', difficulty: '中级', imageSvg: '中胸', imageUrl: 'https://images.pexels.com/photos/13993574/pexels-photo-13993574.jpeg', videoPath: '', weight: '0'),
  Exercise(id: '10035', name: '单臂中位绳索夹胸', categoryPath: '力量训练 / 胸部训练 / 中胸', description: '单侧孤立，补强弱侧中胸，感受单侧胸部收缩，改善左右胸不对称。', tips: ['单侧训练','滑轮调至胸部齐平','身体微微前倾','改善左右胸不对称'], sets: 3, reps: 12, restSeconds: '45', difficulty: '中级', imageSvg: '中胸', imageUrl: 'https://images.pexels.com/photos/29218860/pexels-photo-29218860/free-photo-of-man-doing-lat-pulldown-exercise-in-gym.jpeg', videoPath: '', weight: '0'),
  Exercise(id: '10036', name: '平板卧推底部停顿', categoryPath: '力量训练 / 胸部训练 / 中胸', description: '下放到中胸位置停顿1-2秒，消除惯性，强迫中胸发力，突破平台。', tips: ['杠铃或哑铃平板','下放到中胸位置停顿1-2秒','消除惯性强迫中胸发力','突破平台期'], sets: 4, reps: 8, restSeconds: '60', difficulty: '高级', imageSvg: '中胸', imageUrl: 'https://images.pexels.com/photos/31329758/pexels-photo-31329758.jpeg', videoPath: '', weight: '0'),
  Exercise(id: '10037', name: '慢离心平板卧推', categoryPath: '力量训练 / 胸部训练 / 中胸', description: '不加大重量，拉长离心阶段3-4秒下放，提升肌纤维刺激，增肌周期优先。', tips: ['不加大重量','刻意拉长离心阶段','3-4秒缓慢下放','增肌周期优先'], sets: 3, reps: 10, restSeconds: '60', difficulty: '高级', imageSvg: '中胸', imageUrl: 'https://images.pexels.com/photos/17706037/pexels-photo-17706037/free-photo-of-man-exercising-at-gym.jpeg', videoPath: '', weight: '0'),
  Exercise(id: '10038', name: '哑铃旋转平板飞鸟', categoryPath: '力量训练 / 胸部训练 / 中胸', description: '下放掌心朝下，向中间合拢时掌心转为相对，增加胸肌旋转收缩，强化胸中缝。', tips: ['平板凳完全水平','下放掌心朝下','合拢时掌心转为相对','增加旋转收缩强化胸中缝'], sets: 3, reps: 12, restSeconds: '45', difficulty: '中级', imageSvg: '中胸', imageUrl: 'https://images.pexels.com/photos/17210044/pexels-photo-17210044/free-photo-of-man-exercising-at-the-gym.jpeg', videoPath: '', weight: '0'),

  Exercise(id: '10039', name: '下斜杠铃卧推（15-25度）', categoryPath: '力量训练 / 胸部训练 / 下胸', description: '凳子向下倾斜15-25度，脚勾住挡板固定身体。杠铃下放到胸口下沿/乳头偏下位置，小臂垂直地面，向斜上方推起。特点：可上大重量，强化下胸整体厚度，下胸第一复合动作。角度别调太陡，20度左右收益最高。', tips: ['凳调至15-25度下斜','脚勾住挡板固定身体','杠铃落到胸口下沿','垂直推起不要超过35度'], sets: 4, reps: 8, restSeconds: '60', difficulty: '中级', imageSvg: '下胸', imageUrl: 'https://images.pexels.com/photos/4720783/pexels-photo-4720783.jpeg', videoPath: '', weight: '0'),
  Exercise(id: '10040', name: '窄握下斜杠铃卧推', categoryPath: '力量训练 / 胸部训练 / 下胸', description: '握距略窄，强化下胸内侧和胸下沿中缝，三头参与变多。适合肩膀不舒服、想减少肩关节压力时用。', tips: ['握距略窄于常规','强化下胸内侧中缝','三头参与变多','减少肩关节压力'], sets: 3, reps: 10, restSeconds: '60', difficulty: '中级', imageSvg: '下胸', imageUrl: 'https://images.pexels.com/photos/13822300/pexels-photo-13822300.jpeg', videoPath: '', weight: '0'),
  Exercise(id: '10041', name: '下斜哑铃卧推', categoryPath: '力量训练 / 胸部训练 / 下胸', description: '下斜凳15-25度，脚勾稳挡板。哑铃下放充分，向身体两侧下方打开，感受下胸拉伸。优势：两侧独立，活动幅度更大，比杠铃更容易找到下胸拉伸感，修正左右力量差。', tips: ['凳调至15-25度下斜','脚勾稳挡板','哑铃下放充分向两侧打开','修正左右力量差'], sets: 4, reps: 10, restSeconds: '60', difficulty: '中级', imageSvg: '下胸', imageUrl: 'https://images.pexels.com/photos/5837307/pexels-photo-5837307.jpeg', videoPath: '', weight: '0'),
  Exercise(id: '10042', name: '下斜哑铃飞鸟', categoryPath: '力量训练 / 胸部训练 / 下胸', description: '手肘维持固定微弯，不要弯肘做功。哑铃轨迹向斜下方打开，再向内向上合拢。重点：不要把哑铃举到脸上方，合拢终点在胸下沿正上方。专门打磨胸下缘轮廓，改善胸的分离度。', tips: ['凳调至15-25度下斜','手肘固定微弯','合拢终点在胸下沿正上方','不要举到脸上方'], sets: 3, reps: 12, restSeconds: '45', difficulty: '初级', imageSvg: '下胸', imageUrl: 'https://images.pexels.com/photos/14591521/pexels-photo-14591521.jpeg', videoPath: '', weight: '0'),
  Exercise(id: '10043', name: '脚抬高负重俯卧撑', categoryPath: '力量训练 / 胸部训练 / 下胸', description: '脚垫高（箱子/凳子），头低脚高，身体形成下斜。背部放置杠铃片、负重背心增加负荷。适合热身、高次数充血，没有下斜凳的首选替代。脚抬得越高倾斜越大，注意不要腰塌。', tips: ['脚垫高头低脚高','背部可加杠铃片负重','注意不要腰塌','高次数充血热身'], sets: 3, reps: 15, restSeconds: '30', difficulty: '初级', imageSvg: '下胸', imageUrl: 'https://images.pexels.com/photos/38641856/pexels-photo-38641856/free-photo-of-female-athlete-lifting-weights-in-gym.jpeg', videoPath: '', weight: '0'),
  Exercise(id: '10044', name: '下斜器械推胸', categoryPath: '力量训练 / 胸部训练 / 下胸', description: '专门的下斜推胸器械，座椅调低，把手对齐胸下部。背靠实，推起轨迹斜向上。不用维持平衡，安全做大重量力竭组，适合主项后堆容量。', tips: ['座椅调低把手对齐胸下部','背靠实推起轨迹斜向上','不用维持平衡','可安全做力竭组'], sets: 4, reps: 10, restSeconds: '60', difficulty: '中级', imageSvg: '下胸', imageUrl: 'https://images.pexels.com/photos/6844939/pexels-photo-6844939.jpeg', videoPath: '', weight: '0'),
  Exercise(id: '10045', name: '哈克推胸（下胸模式）', categoryPath: '力量训练 / 胸部训练 / 下胸', description: '靠背放低，座椅调高，身体略微倒向下方，把手落点对准胸下沿。极其稳定，可上很大重量，核心消耗小，平台期堆下胸厚度非常好用。', tips: ['靠背放低座椅调高','把手对准胸下沿','极其稳定可上大重量','核心消耗小'], sets: 4, reps: 10, restSeconds: '60', difficulty: '中级', imageSvg: '下胸', imageUrl: 'https://images.pexels.com/photos/18060020/pexels-photo-18060020/free-photo-of-bodybuilder-using-leg-press-at-the-gym.jpeg', videoPath: '', weight: '0'),
  Exercise(id: '10046', name: '蝴蝶机夹胸（低位把手）', categoryPath: '力量训练 / 胸部训练 / 下胸', description: '把手调至低于肩膀高度，身体微微后仰，手臂从高位向下前方合拢，顶峰挤压胸下缘1-2秒。雕刻胸下沿、胸外侧下沿分离度，复合动作后收尾。', tips: ['把手调至低于肩','身体微微后仰','手臂从高位向下前方合拢','顶峰挤压胸下缘1-2秒'], sets: 3, reps: 12, restSeconds: '45', difficulty: '初级', imageSvg: '下胸', imageUrl: 'https://images.pexels.com/photos/27893438/pexels-photo-27893438.png', videoPath: '', weight: '0'),
  Exercise(id: '10047', name: '低位绳索夹胸', categoryPath: '力量训练 / 胸部训练 / 下胸', description: '滑轮调到最低位置，站姿身体微微前倾，手肘保持微弯固定。双手从下方向上向内夹，双手交汇点大约在胸口下方。重点：不要耸肩，靠胸下缘收缩把把手往上捞，不是手臂用力提拉。下胸全程都有张力，对胸下缘线条提升效果极强。', tips: ['滑轮调至最低位','站姿微微前倾','双手从下方向上向内夹','不要耸肩靠胸下缘收缩'], sets: 3, reps: 15, restSeconds: '30', difficulty: '中级', imageSvg: '下胸', imageUrl: 'https://images.pexels.com/photos/28076/pexels-photo.jpg', videoPath: '', weight: '0'),
  Exercise(id: '10048', name: '高位绳索下斜推胸', categoryPath: '力量训练 / 胸部训练 / 下胸', description: '滑轮调最高，躺15-25度下斜凳，握住高位把手，向斜下方推，复刻下斜哑铃卧推轨迹。绳索会持续拉扯，离心阶段下胸持续受力，弥补哑铃杠铃底部容易卸力的短板。', tips: ['滑轮调至最高位','躺15-25度下斜凳','向斜下方推','离心阶段持续张力'], sets: 3, reps: 12, restSeconds: '45', difficulty: '中级', imageSvg: '下胸', imageUrl: 'https://images.pexels.com/photos/37570727/pexels-photo-37570727/free-photo-of-woman-exercising-on-leg-press-machine-in-gym.jpeg', videoPath: '', weight: '0'),
  Exercise(id: '10049', name: '单臂低位绳索夹胸', categoryPath: '力量训练 / 胸部训练 / 下胸', description: '单侧孤立训练，弥补下胸左右不对称，帮助找到单侧下胸收缩感。', tips: ['单侧训练','滑轮调至最低位','身体微微前倾','改善左右下胸不对称'], sets: 3, reps: 12, restSeconds: '45', difficulty: '中级', imageSvg: '下胸', imageUrl: 'https://images.pexels.com/photos/13122465/pexels-photo-13122465.jpeg', videoPath: '', weight: '0'),
  Exercise(id: '10050', name: '下斜卧推底部停顿', categoryPath: '力量训练 / 胸部训练 / 下胸', description: '负重下放到胸下沿，停顿1-2秒再推起，消除惯性，强迫下胸发力，突破平台。', tips: ['杠铃或哑铃下斜','下放到胸下沿停顿1-2秒','消除惯性强迫下胸发力','突破平台期'], sets: 4, reps: 8, restSeconds: '60', difficulty: '高级', imageSvg: '下胸', imageUrl: 'https://images.pexels.com/photos/31028213/pexels-photo-31028213.jpeg', videoPath: '', weight: '0'),
  Exercise(id: '10051', name: '慢离心下斜卧推', categoryPath: '力量训练 / 胸部训练 / 下胸', description: '不增加重量，拉长离心时间，3-4秒下放，强化下胸肌纤维刺激，增肌周期优先。', tips: ['不增加重量','3-4秒缓慢下放','强化下胸肌纤维','增肌周期优先'], sets: 3, reps: 10, restSeconds: '60', difficulty: '高级', imageSvg: '下胸', imageUrl: 'https://images.pexels.com/photos/26977445/pexels-photo-26977445/free-photo-of-woman-exercising-at-a-gym.jpeg', videoPath: '', weight: '0'),
  Exercise(id: '10052', name: '下斜哑铃旋转飞鸟', categoryPath: '力量训练 / 胸部训练 / 下胸', description: '下放掌心朝下，合拢时掌心相对，增加胸肌旋转收缩，强化下胸中缝。', tips: ['凳调至15-25度下斜','下放掌心朝下','合拢时掌心转为相对','强化下胸中缝'], sets: 3, reps: 12, restSeconds: '45', difficulty: '中级', imageSvg: '下胸', imageUrl: 'https://images.pexels.com/photos/4164840/pexels-photo-4164840.jpeg', videoPath: '', weight: '0'),
